--
-- Name: calculate_max_appointments_per_day(character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calculate_max_appointments_per_day(p_doctor_username character varying) RETURNS integer
    LANGUAGE plpgsql
    AS $$

DECLARE

    doctor_start TIME WITHOUT TIME ZONE;

    doctor_end TIME WITHOUT TIME ZONE;

    avg_time_minutes INT;  -- Store avg time in minutes

    total_working_minutes INT;

    max_appointments INT;

    start_timestamp TIMESTAMP;

    end_timestamp TIMESTAMP;

BEGIN

    -- Get the doctor's visiting time and average appointment duration in minutes

    SELECT visiting_time_start, visiting_time_end, avg_time  -- avg_time is stored in minutes

    INTO doctor_start, doctor_end, avg_time_minutes

    FROM doctors

    WHERE username = p_doctor_username;



    -- Debugging: Output the retrieved values

    RAISE NOTICE 'Doctor Start: %, Doctor End: %, Avg Time: %', doctor_start, doctor_end, avg_time_minutes;



    -- Convert doctor_start and doctor_end to timestamps

    start_timestamp := CURRENT_DATE + doctor_start;

    end_timestamp := CURRENT_DATE + doctor_end;



    -- If the doctor's end time is earlier than the start time, add 1 day to the end timestamp

    IF end_timestamp < start_timestamp THEN

        end_timestamp := end_timestamp + INTERVAL '1 day';

        RAISE NOTICE 'Crosses Midnight: Adjusted End Time: %', end_timestamp;

    END IF;



    -- Calculate total working minutes between start and end time

    total_working_minutes := EXTRACT(EPOCH FROM (end_timestamp - start_timestamp)) / 60;

    RAISE NOTICE 'Total Working Minutes: %', total_working_minutes;



    -- Calculate the maximum number of appointments

    IF avg_time_minutes > 0 THEN

        max_appointments := total_working_minutes / avg_time_minutes;

        RAISE NOTICE 'Max Appointments: %', max_appointments;

    ELSE

        max_appointments := 0; -- If avg_time is invalid, return 0 appointments

    END IF;



    RETURN max_appointments;

END;

$$;


ALTER FUNCTION public.calculate_max_appointments_per_day(p_doctor_username character varying) OWNER TO postgres;

--
-- Name: cancel_appointment(character varying, character varying, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_appointment(p_patient_username character varying, p_doctor_username character varying, p_appointment_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

    canceled_time TIME WITHOUT TIME ZONE;

    doctor_avg_time INT;

BEGIN

    -- Retrieve the appointment time to be canceled

    SELECT appointment_time INTO canceled_time

    FROM appointments

    WHERE patient_username = p_patient_username

      AND doctor_username = p_doctor_username

      AND appointment_date = p_appointment_date;



    IF canceled_time IS NULL THEN

        RAISE EXCEPTION 'No appointment found for patient % with doctor % on %',

            p_patient_username, p_doctor_username, p_appointment_date;

    END IF;



    -- Retrieve the doctor's average appointment time

    SELECT doctors.avg_time INTO doctor_avg_time

    FROM doctors

    WHERE username = p_doctor_username;



    -- Delete the appointment

    DELETE FROM appointments

    WHERE patient_username = p_patient_username

      AND doctor_username = p_doctor_username

      AND appointment_date = p_appointment_date;



    -- Adjust subsequent appointments

    UPDATE appointments

    SET appointment_time = appointment_time - (doctor_avg_time * INTERVAL '1 minute')

    WHERE doctor_username = p_doctor_username

      AND appointment_date = p_appointment_date

      AND appointment_time > canceled_time;



    RAISE NOTICE 'Appointment canceled for patient % with doctor % on %',

        p_patient_username, p_doctor_username, p_appointment_date;

END;

$$;


ALTER FUNCTION public.cancel_appointment(p_patient_username character varying, p_doctor_username character varying, p_appointment_date date) OWNER TO postgres;

