--
-- Name: reschedule_appointment(character varying, character varying, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reschedule_appointment(p_patient_username character varying, p_doctor_username character varying, old_date date, new_date date) RETURNS void
    LANGUAGE plpgsql
    AS $$

DECLARE

    to_cancel_appointment_time TIME WITHOUT TIME ZONE;

BEGIN

    -- Get the old appointment time

    SELECT appointment_time INTO to_cancel_appointment_time

    FROM appointments

    WHERE patient_username = p_patient_username

      AND doctor_username = p_doctor_username

      AND appointment_date = old_date;



    -- Cancel the old appointment

    PERFORM cancel_appointment(p_patient_username, p_doctor_username, old_date);



    -- Schedule a new appointment

    PERFORM schedule_appointment(p_patient_username, p_doctor_username, new_date);

END;

$$;


ALTER FUNCTION public.reschedule_appointment(p_patient_username character varying, p_doctor_username character varying, old_date date, new_date date) OWNER TO postgres;

--
-- Name: reset_user_password(character varying, character, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.reset_user_password(p_username character varying, p_answer_hash character, p_new_password_hash character) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    is_verified BOOLEAN;
BEGIN
    -- verify the security answer
    is_verified := verify_security_question(p_username, p_answer_hash);

    -- if verified, update password
    IF is_verified THEN
        UPDATE users
        SET password_hash = p_new_password_hash
        WHERE username = p_username;

        RETURN true; -- successful
    ELSE
        RETURN false; -- security answer did not match
    END IF;
    
END;
$$;


