--
-- Name: signup_users(character varying, character varying, character, public.users_type, text, character, character, public.bloodgroup, text, character varying, public.day_of_week[], time without time zone, time without time zone, date, character varying, text[], integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.signup_users(p_username character varying, p_name character varying, p_password_hash character, p_users_type public.users_type, p_security_question text, p_security_answer_hash character, c_phone_no character, pt_blood_group public.bloodgroup, pt_complexities text, dc_specialization character varying, dc_visiting_days public.day_of_week[], dc_visiting_time_start time without time zone, dc_visiting_time_end time without time zone, pt_dob date, pt_gender character varying, degrees text[], p_fee integer, p_avg_time integer) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN

    -- validate username: only lowercase letters, ., _, -, @
     IF p_username !~ '^[a-z0-9._\-@]+$' THEN
        RAISE EXCEPTION 'Invalid Username. Valid characters in username: a-z, 0-9, ., _, -, @';
    END IF;
    -- insert the user into the users table
    INSERT INTO users (
        username,
		name,
        password_hash,
        users_type,
        security_question,
        security_answer_hash
    ) VALUES (
        p_username,
		p_name,
        p_password_hash,
        p_users_type,
        p_security_question,
        p_security_answer_hash
    );

    -- based on users_type, call the specific function 
    IF p_users_type = 'patient' THEN
        PERFORM public.signup_patient(
            p_username,
            c_phone_no,
            pt_blood_group,
            pt_complexities,
			pt_dob,
			pt_gender
        );
    ELSIF p_users_type = 'doctor' THEN
        PERFORM public.signup_doctor(
            p_username,
            c_phone_no,
            dc_specialization,
            dc_visiting_days,
            dc_visiting_time_start,
            dc_visiting_time_end,
			pt_gender,
			degrees,
			p_fee,
			p_avg_time
        );
    ELSE
        RAISE EXCEPTION 'Invalid user type: %', p_users_type;
    END IF;

END;
$_$;


ALTER FUNCTION public.signup_users(p_username character varying, p_name character varying, p_password_hash character, p_users_type public.users_type, p_security_question text, p_security_answer_hash character, c_phone_no character, pt_blood_group public.bloodgroup, pt_complexities text, dc_specialization character varying, dc_visiting_days public.day_of_week[], dc_visiting_time_start time without time zone, dc_visiting_time_end time without time zone, pt_dob date, pt_gender character varying, degrees text[], p_fee integer, p_avg_time integer) OWNER TO postgres;

--
-- Name: validate_blood_group(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_blood_group() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Check if the blood_group is valid
    IF NEW.blood_group NOT IN ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-') THEN
        RAISE EXCEPTION 'Invalid blood group: %', NEW.blood_group;
    END IF;
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_blood_group() OWNER TO postgres;

--
-- Name: validate_phone_no(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.validate_phone_no() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    phone CHAR(11);
BEGIN
    -- Check if each phone number in the array is exactly 11 digits
    FOREACH phone IN ARRAY NEW.phone_no
    LOOP
        IF length(phone) != 11 THEN
            RAISE EXCEPTION 'Phone number % must be 11 digits long', phone;
        END IF;
    END LOOP;

    -- Ensure that the phone numbers are unique in the table
    IF EXISTS (
        SELECT 1
        FROM blood_repo
        WHERE NEW.phone_no && phone_no
    ) THEN
        RAISE EXCEPTION 'Phone number already exists';
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION public.validate_phone_no() OWNER TO postgres;

--
-- Name: verify_security_question(character varying, character); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.verify_security_question(p_username character varying, p_answer_hash character) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
    stored_answer_hash CHAR(128);
BEGIN
    -- retrieve the stored security answer
    SELECT security_answer_hash
    INTO stored_answer_hash
    FROM users
    WHERE username = p_username;

    -- return true if the answer hash matches
    RETURN stored_answer_hash = p_answer_hash;

END;
$$;


ALTER FUNCTION public.verify_security_question(p_username character varying, p_answer_hash character) OWNER TO postgres;

